<?php
// Runtime readiness only. Does not install, upgrade, or change application data.
header('Content-Type: application/json');
$ismoodle = getenv('MOODLE_DB_PASSWORD') !== false;
$database = $ismoodle ? 'moodle' : 'rosariosis';
$password = getenv($ismoodle ? 'MOODLE_DB_PASSWORD' : 'ROSARIO_DB_PASSWORD');
// Passwords generated by init-env.py are hexadecimal; reject invalid connection syntax.
if (!is_string($password) || !preg_match('/^[a-f0-9]{48}$/D', $password)) {
    http_response_code(503);
    echo json_encode(['runtime' => 'configuration error']);
    exit;
}
$connection = @pg_connect("host=db dbname=$database user=$database password=$password connect_timeout=3");
if (!$connection) {
    http_response_code(503);
    echo json_encode(['runtime' => 'database unavailable']);
    exit;
}
$table = $ismoodle ? 'public.mdl_config' : 'public.config';
$result = pg_query_params($connection, 'SELECT to_regclass($1)', [$table]);
echo json_encode([
    'runtime' => 'ready',
    'schema_present' => $result && pg_fetch_result($result, 0, 0) !== null,
]);
